old_string:
for (const variantId of selected_variant_external_ids) {
  try {
    const variantGid = `gid://shopify/ProductVariant/${variantId}`;
    const variantData = await shopify.graphql<ProductVariantQueryResult>(
      `query GetVariant($id: ID!) {
         productVariant(id: $id) {
           id
           price
           availableForSale
           legacyResourceId
         }
       }`,
      { id: variantGid },
    );

    if (!variantData.productVariant) {
      warnings.push(`variant ${variantId} not found in Shopify`);
      continue;
    }
    if (!variantData.productVariant.availableForSale) {
      warnings.push(`variant ${variantId} is not available for sale`);
    }

    originalTotalMinor += money.toMinorUnits(variantData.productVariant.price, currency);
  } catch (err) {
    warnings.push(`could not fetch price for variant ${variantId}: ${String(err)}`);
  }
}

new_string:
// Use the provided variant GIDs (sourced from live_variant_gid on bundle components)
// to query variant prices from the Shopify Admin API. GIDs are passed in directly
// from the request — no local GID construction.
for (let i = 0; i < selected_variant_external_ids.length; i++) {
  const variantId = selected_variant_external_ids[i];
  const variantGid = selected_variant_gids[i]; // sourced from live_variant_gid
  if (!variantId || !variantGid) continue;
  try {
    const variantData = await shopify.graphql<ProductVariantQueryResult>(
      `query GetVariant($id: ID!) {
         productVariant(id: $id) {
           id
           price
           availableForSale
           legacyResourceId
         }
       }`,
      { id: variantGid },
    );

    if (!variantData.productVariant) {
