      continue;
    }
    if (!variantData.productVariant.availableForSale) {
      warnings.push(`variant ${variantId} is not available for sale`);
    }

    originalTotalMinor += money.toMinorUnits(variantData.productVariant.price, currency);
  } catch (err) {
